+        }
+
+        System.out.println(join(tree.preOrder()));
+    }
+
+    private static String join(Iterable<?> values) {
+        StringJoiner joiner = new StringJoiner(" ");
+        for (Object value : values) {
+            joiner.add(String.valueOf(value));
+        }
+        return joiner.toString();
+    }
+}
